        "set_frequency(0, ${center_freq})",
        "set_frequency_correction(0, ${freq_correction})",
        "self.set_${id}_gain_mode(0, ${agc})",
        "self.set_${id}_gain(0, 'TUNER', ${gain})",
        "self.set_${id}_bias(${bias})"
      ]
    },
