      "${ ((bandwidth<=52000000) and (bandwidth>=200000)) }",
      "${ ((frequency<=6000000000) and (frequency>=70000000)) }",
      "${ ((filter_source!=\"'Design'\") or (fpass<=samplerate)) }",
      "${ ((filter_source!=\"'Design'\") or (fstop<=samplerate)) }",
      "${ ((filter_source!=\"'Design'\") or (fstop>fpass)) }"
    ],
    "templates": {
      "imports": "from gnuradio import iio",
      "make": "iio.fmcomms2_source_${type.type}(${uri} if ${uri} else iio.get_pluto_uri(), [True, True], ${buffer_size})\nself.${id}.set_len_tag_key(${len_tag_key})\nself.${id}.set_frequency(${frequency})\nself.${id}.set_samplerate(${samplerate})\nself.${id}.set_gain_mode(0, ${gain1})\nself.${id}.set_gain(0, ${manual_gain1})\nself.${id}.set_quadrature(${quadrature})\nself.${id}.set_rfdc(${rfdc})\nself.${id}.set_bbdc(${bbdc})\nself.${id}.set_filter_params(${filter_source}, ${filter}, ${fpass}, ${fstop})\n",
      "callbacks": [
        "set_frequency(${frequency})",
        "set_samplerate(${samplerate})",
        "set_gain_mode(0, ${gain1})",
        "set_gain(0, ${manual_gain1})",
        "set_quadrature(${quadrature})",
        "set_rfdc(${rfdc})",
        "set_bbdc(${bbdc})",
        "set_filter_params(${filter_source}, ${filter}, ${fpass}, ${fstop})"
      ]
    },
    "file_format": 1
  },
  "parse_status": "success",
  "parse_errors": []
}

